import json
from pathlib import Path

ROOT = Path('/app/applet')
COL = json.loads((ROOT / 'English/englishCollocations.json').read_text(encoding='utf8'))
VOCAB = json.loads((ROOT / 'English/englishVocabulary.json').read_text(encoding='utf8'))
PV = json.loads((ROOT / 'English/englishPhrasalVerbs.json').read_text(encoding='utf8'))
REG = json.loads((ROOT / 'English/englishRegional.json').read_text(encoding='utf8'))

taken = set()
for src in (COL, VOCAB, PV):
    for d in src:
        for c in d['cards']:
            taken.add(c['term'].lower())
for d in REG:
    for c in d['cards']:
        taken.add(c['american']['term'].lower())
        taken.add(c['british']['term'].lower())

