added = 0
for deck_id, level, title, cards_spec in NEW_COL_DECKS:
    cards = []
    for item in cards_spec:
        anchor, term, meaning, syn, ant, ex1, tr1, ex2, tr2 = item
        key = term.lower()
        if key in taken:
            continue
        taken.add(key)
        cards.append({
            "anchor": anchor,
            "term": term,
            "meaning": meaning,
            "synonyms": syn,
            "antonyms": ant,
            "sentence": ex1,
            "translation": tr1,
            "extraExamples": [{"sentence": ex2, "translation": tr2}],
        })
        added += 1
    if cards:
        COL.append({
            "id": deck_id,
            "level": level,
            "title": title,
            "cards": cards,
        })

(ROOT / 'English/englishCollocations.json').write_text(
    json.dumps(COL, ensure_ascii=False, indent=2) + "\n", encoding='utf8'
)
print(f"Collocations updated: {len(COL)} decks, added {added}, total {sum(len(d['cards']) for d in COL)}")
